/**
 * The only DDMS read that deliberately looks outside the showroom in the query string, and the reason is the product's whole premise. A DMS keeps the stock ledger against a dealer code, because a dealer code is what it thinks a business is. An owner with three outlets gets three ledgers and no way to ask whether the part a customer has been waiting three days for is on a shelf in the next branch.
 * The cross-branch scope comes from the session, never from the request, so widening the read cannot widen it past the owner. Row-level security is the backstop underneath that.
 * @summary The parts counter, read across every outlet the owner holds
 */
export const GetSparesWorklistQueryParams = zod.object({
  "showroomId": zod.coerce.number().int()
})

export const GetSparesWorklistResponse = zod.object({
  "summary": zod.object({
  "total": zod.number().int(),
  "byState": zod.record(zod.string(), zod.number().int()),
  "needsAction": zod.number().int(),
  "availableElsewhere": zod.number().int().describe('Customers waiting for a part the company already owns, in another outlet. No single branch\'s system can produce this number.\n'),
  "stockoutBlocking": zod.number().int(),
  "belowReorder": zod.number().int(),
  "idleCapital": zod.number().describe('Cost of stock that has not moved. Capital, not inventory.'),
  "lastSyncedAt": zod.string().nullish()
}),
  "rows": zod.array(zod.object({
  "partNo": zod.string(),
  "partDesc": zod.string().nullish(),
  "showroomId": zod.number().int(),
  "showroomCode": zod.string().nullish(),
  "dealerCode": zod.string(),
  "binLocation": zod.string().nullish(),
  "dms": zod.object({
  "qtyOnHand": zod.number().int(),
  "qtyReserved": zod.number().int(),
  "qtyFree": zod.number().int().describe('On hand minus reserved. What the counter can issue today.'),
  "reorderLevel": zod.number().int(),
  "mrpAmount": zod.number().nullish(),
  "costAmount": zod.number().nullish(),
  "lastReceivedDate": zod.string().nullish(),
  "lastIssuedDate": zod.string().nullish(),
  "onOrderQty": zod.number().int(),
  "onOrderEtaDate": zod.string().nullish()
}).describe('What this branch\'s own ledger holds.'),
  "ddms": zod.object({
  "transferRequestedAt": zod.string().nullable(),
  "transferFromShowroomId": zod.number().int().nullable(),
  "reorderRaisedAt": zod.string().nullable()
}).describe('Ours. An inter-branch transfer is not an event either branch\'s system has a concept of, because each one only knows its own shelf.\n'),
  "waitingJobCards": zod.array(zod.object({
  "jcNo": zod.string(),
  "customerName": zod.string().nullish(),
  "daysWaiting": zod.number().int()
})).describe('Open job cards at this outlet held up on this exact part.'),
  "availableAt": zod.array(zod.object({
  "showroomId": zod.number().int(),
  "showroomCode": zod.string().nullish(),
  "qtyFree": zod.number().int(),
  "binLocation": zod.string().nullish()
})).describe('The same part, free, at another outlet this owner holds.'),
  "shortAt": zod.array(zod.object({
  "showroomId": zod.number().int(),
  "showroomCode": zod.string().nullish(),
  "qtyFree": zod.number().int(),
  "reorderLevel": zod.number().int(),
  "onOrderQty": zod.number().int()
})).describe('The same part, at or below its reorder level, at another outlet. The inverse finding: eight pads nobody here has ever issued are not a write-off if the branch that sells the model is about to buy more.\n'),
  "state": zod.enum(['AVAILABLE_ELSEWHERE', 'STOCKOUT_BLOCKING', 'ORDER_OVERDUE', 'BELOW_REORDER', 'FULLY_RESERVED', 'DEAD_STOCK', 'OK']).describe('AVAILABLE_ELSEWHERE is the one that justifies the module: a customer is waiting for a part the company already owns, on a shelf in another outlet, and neither branch\'s system can see the other\'s. Everything else here a good storeman would eventually catch on their own screen.\nFULLY_RESERVED is the quiet one. The shelf holds four and every one is promised to an open job card, so the counter can issue none — and only the first of those numbers is on the storeman\'s screen.\n'),
  "note": zod.string().nullish(),
  "actionRequired": zod.string().nullish(),
  "daysSinceIssued": zod.number().int().nullish(),
  "idleCapital": zod.number().nullish().describe('Cost of stock sitting still. What makes dead stock a decision.'),
  "lastSyncedAt": zod.string()
}))
})


/**
 * The CRM mirror. Two things here appear on no screen the dealer has: how many minutes are left on a manufacturer-generated lead's response window — the industry mandate is thirty, and future lead allocation depends on it — and which live enquiries are assigned to somebody who has left.
 * The second needs the enquiry mirror joined to the staff mirror. The dealer's CRM knows the assignment and their HR records know the leaving date; neither knows both.
 * @summary Enquiries, the manufacturer response clock, and leads with no owner
 */
export const GetLeadWorklistQueryParams = zod.object({
  "showroomId": zod.coerce.number().int(),
  "stage": zod.coerce.string().optional()
})

export const GetLeadWorklistResponse = zod.object({
  "summary": zod.object({
  "total": zod.number().int(),
  "byState": zod.record(zod.string(), zod.number().int()),
  "needsAction": zod.number().int(),
  "slaBreached": zod.number().int(),
  "orphaned": zod.number().int().describe('Live leads with nobody active against them.'),
  "slaMinutes": zod.number().int().describe('The response mandate being measured against.'),
  "lastSyncedAt": zod.string().nullish()
}),
  "rows": zod.array(zod.object({
  "enqId": zod.string(),
  "dealerCode": zod.string(),
  "showroomId": zod.number().int(),
  "customerName": zod.string().nullish(),
  "customerMobile": zod.string().nullish(),
  "modelInterest": zod.string().nullish(),
  "dms": zod.object({
  "source": zod.string(),
  "grade": zod.string().nullish(),
  "stage": zod.string(),
  "enquiredAt": zod.string().nullish(),
  "firstContactAt": zod.string().nullish(),
  "nextFollowUpDate": zod.string().nullish(),
  "assignedEmpCode": zod.string().nullish(),
  "assignedEmpName": zod.string().nullish(),
  "assignedEmpActive": zod.boolean(),
  "assignedEmpLeftOn": zod.string().nullish(),
  "lostReason": zod.string().nullish(),
  "convertedDealId": zod.string().nullish()
}).describe('What the dealer\'s CRM holds.'),
  "ddms": zod.object({
  "reassignedToEmpCode": zod.string().nullable(),
  "contactedAt": zod.string().nullable().describe('When \*we\* recorded a contact. Never conflated with the DMS\'s own firstContactAt above — see slaNote.\n'),
  "contactChannel": zod.string().nullish()
}).describe('Ours. The DMS has no column for any of this.'),
  "state": zod.enum(['SLA_BREACHED', 'CLOCK_RUNNING', 'NO_OWNER', 'UNCONTACTED', 'FOLLOW_UP_OVERDUE', 'ON_TRACK', 'CONVERTED', 'LOST']).describe('SLA_BREACHED and CLOCK_RUNNING apply only to manufacturer-generated leads, which carry a timed first-response mandate. NO_OWNER means the assigned executive has left and nobody has picked the lead up — worse than late, because late at least implies somebody is on it.\n'),
  "slaNote": zod.string().nullish().describe('Present only when we have logged a contact and the dealer\'s CRM has not. The integration is read-only, so this gap cannot be closed from here — and the manufacturer measures their field, not ours. Saying so is the difference between a useful screen and one that tells an owner they are compliant when the OEM\'s report disagrees.\n'),
  "note": zod.string().nullish(),
  "actionRequired": zod.string().nullish(),
  "responseMinutes": zod.number().int().nullish().describe('Minutes to first contact, or minutes elapsed so far when nobody has made contact at all.\n'),
  "minutesToSla": zod.number().int().nullish().describe('Minutes left in the window. Negative once it has closed.'),
  "followUpDaysOverdue": zod.number().int(),
  "lastSyncedAt": zod.string()
}))
})


/**
 * @summary Pull deal, vehicle and customer data from the dealer's DMS
 */




export const IngestDmsPullBody = zod.object({
  "dealId": zod.string().min(1).optional().describe('The dealer\'s own deal or booking identifier, e.g. HMC-DL-2026-000183. Preferred: a deal is customer plus vehicle plus finance, where a chassis is only the vehicle.\n'),
  "chassisNo": zod.string().min(1).optional().describe('Chassis number (VIN) of the allocated unit, e.g. MBLKAR0921NK18337. Present on Form 21 before any RC exists, and unlike a registration number it never changes on transfer or re-registration.\n')
}).describe('Identifies the deal to pull. Deliberately not keyed on a registration number: under the Motor Vehicles Act an RTO will not register a vehicle without live insurance, so a new vehicle has no registration number at the moment the policy is bought. The keys that do exist at that point are the dealer\'s own deal identifier and the chassis number of the allocated stock unit. Supply at least one — dealId wins if both are given, because it resolves a whole deal rather than just a vehicle.\n')

export const IngestDmsPullResponse = zod.object({
  "fields": zod.object({
  "vehicleMake": zod.string(),
  "vehicleModel": zod.string(),
  "vehicleVariant": zod.string(),
  "vehicleEngineNumber": zod.string(),
  "vehicleChassisNumber": zod.string(),
  "vehicleExShowroomPrice": zod.number(),
  "vehicleDateOfPurchase": zod.coerce.date(),
  "ownerFullName": zod.string(),
  "ownerBillingAddress": zod.string(),
  "ownerPincode": zod.number(),
  "ownerPhoneNumber": zod.string(),
  "ownerEmail": zod.string(),
  "ownerDateOfBirth": zod.coerce.date(),
  "ownerIdProofType": zod.enum(['AADHAR', 'PAN', 'PASSPORT', 'DRIVING_LICENSE', 'VOTER_ID']),
  "ownerIdProofNumber": zod.string(),
  "rtoRegistrationCity": zod.string(),
  "rtoRegistrationState": zod.string(),
  "rtoCode": zod.string()
}).describe('Normalised vehicle + owner + RTO fields for an MSA payload'),
  "confidence": zod.record(zod.string(), zod.number()).describe('Per-field confidence score 0-1'),
  "rawText": zod.string().nullish().describe('Raw extracted text (OCR\/scrape) for display in the review panel'),
  "engineUsed": zod.string().nullish().describe('OCR engine that actually produced this result. Null for non-OCR sources.'),
  "isDemoData": zod.boolean().optional().describe('True when the result came from the stub engine and contains fabricated values.'),
  "attempts": zod.array(zod.object({
  "engineId": zod.enum(['paddleocr', 'qwen-vl', 'olmocr', 'gpt-vision', 'gemini', 'openrouter', 'stub']),
  "ok": zod.boolean(),
  "error": zod.string().nullable(),
  "durationMs": zod.number()
}).describe('One engine attempt within a fallback chain')).optional().describe('Every engine tried, in order, including failures. OCR only.'),
  "document": zod.union([zod.object({
  "documentType": zod.enum(['RC_BOOK', 'DEALER_INVOICE', 'AADHAAR', 'PAN', 'DRIVING_LICENCE', 'INSURANCE_POLICY', 'OTHER']),
  "documentTypeConfidence": zod.number(),
  "issuer": zod.string().nullable(),
  "summary": zod.string(),
  "fields": zod.array(zod.object({
  "label": zod.string().describe('The label exactly as printed on the document'),
  "value": zod.string(),
  "group": zod.enum(['vehicle', 'owner', 'rto', 'policy', 'other']),
  "confidence": zod.number()
}).describe('One labelled value, using the document\'s own printed label')),
  "rawText": zod.string().nullish()
}).describe('Stage 1 — what the document is and everything printed on it'),zod.null()]).optional().describe('Stage 1 output — the document as the model actually read it.'),
  "provenance": zod.record(zod.string(), zod.string().nullable()).optional().describe('MSA field name to the document label it came from, null if unmapped.'),
  "mappingMethod": zod.union([zod.literal('llm'),zod.literal('rules'),zod.literal(null)]).nullish().describe('How stage 2 resolved — an LLM call, or the deterministic fallback.'),
  "tenant": zod.union([zod.object({
  "showroomId": zod.number().int(),
  "showroomCode": zod.string(),
  "showroomName": zod.string(),
  "ownerId": zod.number().int(),
  "ownerCode": zod.string(),
  "ownerName": zod.string(),
  "insuranceChannel": zod.union([zod.literal('BROKER'),zod.literal('DIRECT_AGENT'),zod.literal(null)]).nullish().describe('How this showroom reaches insurers for deals from this DMS account. Held per account rather than per showroom because the arrangement belongs to the legal entity — one outlet may go through a broker platform while another holds its own agency code.\n')
}).describe('Resolved from the OEM\'s dealer code via showroom_dms_accounts. Null when that dealer code is not mapped to a showroom — a configuration gap, and reported as one rather than guessed at.\n'),zod.null()]).optional().describe('Which showroom, and through it which owner, a pulled deal belongs to. DMS pull only.\n'),
  "dealContext": zod.record(zod.string(), zod.unknown()).optional().describe('Facts the DMS supplies that the flat MSA payload has no room for — cubic capacity, motor kW, nominee, hypothecation, seating, invoice, and a `gaps` list naming what must be asked. DMS pull only.\nDeliberately loose for now. The authoritative shape is `DmsDealContext` in api-server\/src\/lib\/dms\/hero-adapter.ts, and it will be pinned down here when it is wired through \/ingest\/push into the applications columns that hold it. Declaring it loosely is better than leaving the response undeclared.\n')
}).describe('Extracted MSA fields from any ingest source')


